-- Catalog Hash

function ARKANA_ComputeCatalogHash()
    local ids = {}
    for id in pairs(ARKANA_CardData) do ids[#ids + 1] = id end
    table.sort(ids)
    local parts = {}
    for _, id in ipairs(ids) do
        parts[#parts + 1] = cardToHashString(ARKANA_CardData[id])
    end
    return CRC32(table.concat(parts, "\n"))
end
